/* RFI Modul 5(c): illustrative incremental contribution, not official Bank pricing/profit. */
const XS_KINDS=['Tabungan','Deposito','Kredit'];
let xsCalcCustomer='',xsCalcScenario='C';
const xsCalcDrafts=new Map();
function xsCalcProducts(kind){return activeMaster('products').filter(p=>{const type=typeof catalogType==='function'?catalogType(p):p.category||'';return kind==='Kredit'?/^Kredit/i.test(type):type===kind})}
function xsCalcKey(id){return [authUser?.id||'simulation',typeof activeBranch==='undefined'?'':activeBranch,id].join('|')}
function xsCalcDefault(){return {months:12,rows:XS_KINDS.map((kind,i)=>({kind,product:xsCalcProducts(kind)[0]?.name||'',amount:[100000000,200000000,150000000][i],rate:[1,3,12][i],ftp:[4,4,6][i],cost:kind==='Kredit'?1:0,risk:kind==='Kredit'?2:0,fee:0}))}}
function xsCalcDraft(id){const key=xsCalcKey(id);if(!xsCalcDrafts.has(key))xsCalcDrafts.set(key,xsCalcDefault());return xsCalcDrafts.get(key)}
function xsCalcNumber(v,label,max){if(v===''||v===null||typeof v==='boolean'||!Number.isFinite(Number(v))||Number(v)<0||Number(v)>max)throw Error(label+' harus berupa angka 0–'+max+'.');return Number(v)}
function xsCalcCompute(d){const months=xsCalcNumber(d.months,'Periode',60);if(!Number.isInteger(months)||months<1)throw Error('Periode harus 1–60 bulan penuh.');if(!Array.isArray(d.rows)||d.rows.length!==3||d.rows.some((r,i)=>r.kind!==XS_KINDS[i]))throw Error('Komponen simulasi tidak valid.');const rows=d.rows.map(r=>{const amount=xsCalcNumber(r.amount,'Saldo / outstanding',1e12),rate=xsCalcNumber(r.rate,'Bunga',100),ftp=xsCalcNumber(r.ftp,'FTP',100),cost=xsCalcNumber(r.cost,'Biaya',100),risk=xsCalcNumber(r.risk,'Risiko',100),fee=xsCalcNumber(r.fee,'Fee neto',1e12);if(!amount&&fee)throw Error('Fee neto memerlukan saldo / outstanding tambahan.');const annual=r.kind==='Kredit'?rate-ftp-cost-risk:ftp-rate;const margin=amount*annual/100*months/12;return {...r,amount,rate,ftp,cost,risk,fee,annual,margin,total:margin+fee}});const scenarios=[{id:'A',name:'Tabungan + Deposito',indices:[0,1]},{id:'B',name:'Tabungan + Kredit',indices:[0,2]},{id:'C',name:'Tabungan + Deposito + Kredit',indices:[0,1,2]}].map(s=>({...s,total:s.indices.reduce((n,i)=>n+rows[i].total,0)}));return {months,rows,scenarios}}
function xsCalcOpen(id){if(!c360Customer(id))return toast('Customer tidak tersedia.');xsCalcCustomer=id;xsCalcScenario='C';c360Tab='Cross-sell';renderContent()}
function xsCalcClose(){xsCalcCustomer='';renderContent()}
function xsCalcInput(name,value){const p=c360Customer(xsCalcCustomer);if(!p)return;const d=xsCalcDraft(p.id);if(name==='months')d.months=value;else{const [index,key]=name.split(':');if(!['product','amount','rate','ftp','cost','risk','fee'].includes(key)||!d.rows[Number(index)])return;d.rows[Number(index)][key]=value}xsCalcRefresh()}
function xsCalcSelectScenario(id){if(!['A','B','C'].includes(id))return;xsCalcScenario=id;xsCalcRefresh()}
function xsCalcSample(){const p=c360Customer(xsCalcCustomer);if(!p)return;xsCalcDrafts.set(xsCalcKey(p.id),xsCalcDefault());renderContent()}
function xsCalcField(label,name,value,max,unit=''){return '<label>'+E(label)+(unit?' <span>'+E(unit)+'</span>':'')+'<input aria-label="'+E(label)+'" type="number" inputmode="decimal" min="'+(name==='months'?1:0)+'" max="'+max+'" step="'+(name==='months'?1:'any')+'" value="'+E(String(value))+'" oninput="xsCalcInput('+E(JSON.stringify(name))+',this.value)"></label>'}
function xsCalcProductForm(r,i){const products=xsCalcProducts(r.kind);return '<section class="xs-product"><h3>'+E(r.kind)+'</h3><label>Produk<select aria-label="Produk '+E(r.kind)+'" onchange="xsCalcInput('+E(JSON.stringify(i+':product'))+',this.value)"><option value="">Pilih produk aktif</option>'+products.map(p=>'<option value="'+E(p.name)+'" '+(p.name===r.product?'selected':'')+'>'+E(p.name)+'</option>').join('')+'</select></label>'+xsCalcField(r.kind==='Kredit'?'Outstanding tambahan rata-rata':'Saldo tambahan rata-rata',i+':amount',r.amount,1e12,'Rp')+'<div class="xs-rate-grid">'+xsCalcField(r.kind==='Kredit'?'Bunga kredit':'Bunga nasabah',i+':rate',r.rate,100,'% / tahun')+xsCalcField('FTP '+r.kind,i+':ftp',r.ftp,100,'% / tahun')+(r.kind==='Kredit'?xsCalcField('Biaya asumsi',i+':cost',r.cost,100,'% / tahun')+xsCalcField('Risiko kredit asumsi',i+':risk',r.risk,100,'% / tahun'):'')+'</div>'+xsCalcField('Fee neto '+r.kind,i+':fee',r.fee,1e12,'Rp, satu kali')+'<small>Isi saldo / outstanding tambahan, di luar posisi produk existing. Nilai 0 berarti tidak ada tambahan produk ini.</small></section>'}
function xsCalcResult(p){const d=xsCalcDraft(p.id);let result;try{result=xsCalcCompute(d)}catch(e){return '<p class="xs-error" role="alert">'+E(e.message)+'</p>'}const chosen=result.scenarios.find(s=>s.id===xsCalcScenario)||result.scenarios[2];return '<div class="xs-scenarios" aria-label="Perbandingan kombinasi">'+result.scenarios.map(s=>'<button type="button" aria-pressed="'+(chosen.id===s.id)+'" class="xs-scenario '+(chosen.id===s.id?'active':'')+'" onclick="xsCalcSelectScenario(\''+s.id+'\')"><span>Skenario '+s.id+'</span><strong>'+E(s.name)+'</strong><b>'+rup(s.total)+'</b><small>Kontribusi indikatif untuk '+result.months+' bulan</small></button>').join('')+'</div><section class="xs-breakdown"><h3>Rincian skenario '+chosen.id+'</h3><p>Hanya tambahan bisnis yang diasumsikan. Hasil negatif tetap ditampilkan.</p><div class="xs-table-wrap"><table><thead><tr><th>Produk</th><th>Spread neto / tahun</th><th>Kontribusi periode</th><th>Fee neto</th><th>Total indikatif</th></tr></thead><tbody>'+chosen.indices.map(i=>{const r=result.rows[i];return '<tr><td>'+E(r.product||r.kind)+'<small>'+E(r.kind)+' · '+rup(r.amount)+'</small></td><td>'+r.annual.toLocaleString('id-ID',{maximumFractionDigits:4})+'%</td><td>'+rup(r.margin)+'</td><td>'+rup(r.fee)+'</td><td>'+rup(r.total)+'</td></tr>'}).join('')+'</tbody><tfoot><tr><th colspan="4">Total kontribusi indikatif</th><th>'+rup(chosen.total)+'</th></tr></tfoot></table></div></section><section class="xs-followup"><h3>Lanjutkan produk yang sudah dikonfirmasi</h3><p>Simulasi ini tidak membuat bundel Opportunity. Setiap produk memiliki Opportunity sendiri. Tinjau kebutuhan dan nilai indikatif sebelum menyimpan.</p><div class="xs-followup-list">'+chosen.indices.map(i=>{const r=result.rows[i],active=db.opps.find(o=>o.profile===p.id&&mine(o)&&o.outcome==='Aktif'&&o.product===r.product),valid=xsCalcProducts(r.kind).some(x=>x.name===r.product),can=!(typeof pocReadOnly==='function'&&pocReadOnly())&&!p.readOnly;return '<article><div><strong>'+E(r.product||'Produk '+r.kind+' belum dipilih')+'</strong><small>'+(!valid?'Pilih produk aktif yang sesuai.':!r.amount?'Isi nominal tambahan untuk menindaklanjuti.':active?'Sudah ada Opportunity aktif.':'Nominal indikatif: '+rup(r.amount))+'</small></div>'+(active?btn('Buka Opportunity',leadCall('go','Opportunity detail',active.id)):can&&valid&&r.amount>0?btn('Buat Opportunity '+r.kind,leadCall('xsCalcOpportunity',p.id,i),true):'<span class="xs-muted">'+(can?'Belum dapat dilanjutkan':'Akses baca')+'</span>')+'</article>'}).join('')+'</div></section>'}
function xsCalcRefresh(){const p=c360Customer(xsCalcCustomer),node=document.querySelector('#xsCalcResults');if(p&&node)node.innerHTML=xsCalcResult(p)}
function xsCalcRender(p){const d=xsCalcDraft(p.id);return '<section class="xs-calculator" aria-label="Cross-Sell Calculator"><div class="xs-heading"><div><small>RFI MODUL 5 · SIMULASI POC</small><h2>Cross-Sell Calculator</h2><p>'+E(p.name)+' · Bandingkan tambahan Tabungan, Deposito, dan Kredit.</p></div>'+btn('Kembali ke peluang cross-sell','xsCalcClose()')+'</div><aside class="xs-notice"><strong>Parameter dummy, bukan pricing resmi BPD Bali</strong><p>Hasil adalah estimasi kontribusi berbasis asumsi, bukan laba bersih, janji pendapatan, penawaran bunga, atau keputusan kredit. Parameter Bank belum terverifikasi.</p></aside><div class="xs-period">'+xsCalcField('Periode simulasi','months',d.months,60,'bulan')+btn('Isi ulang contoh dummy','xsCalcSample()')+'<p>Asumsi berlaku sama sepanjang periode. Fee neto dihitung satu kali. Perubahan tersimpan hanya selama sesi halaman ini.</p></div><details class="xs-method"><summary>Rumus, satuan dan batas perhitungan</summary><p><b>Dana:</b> saldo tambahan rata-rata × (FTP − bunga nasabah) ÷ 100 × bulan ÷ 12 + fee neto.</p><p><b>Kredit:</b> outstanding tambahan rata-rata × (bunga kredit − FTP − biaya asumsi − risiko asumsi) ÷ 100 × bulan ÷ 12 + fee neto.</p><p>FTP adalah nilai transfer dana internal asumsi. Biaya dan risiko memakai ekuivalen persentase tahunan. Fee neto sudah memperhitungkan biaya langsung fee. Nominal pokok tidak dihitung sebagai pendapatan. Model rata-rata ini belum menghitung jadwal amortisasi, pajak, biaya overhead lengkap, perubahan saldo, atau probabilitas closing.</p></details><div class="xs-products">'+d.rows.map(xsCalcProductForm).join('')+'</div><div id="xsCalcResults">'+xsCalcResult(p)+'</div></section>'}
function xsCalcSnapshot(result,scenario,row){return ['Cross-Sell Calculator · DUMMY POC', 'Skenario '+scenario.id+': '+scenario.name,'Periode: '+result.months+' bulan','Produk: '+row.product,'Saldo / outstanding tambahan rata-rata: '+rup(row.amount),'Bunga / FTP / biaya / risiko (% per tahun): '+[row.rate,row.ftp,row.cost,row.risk].join(' / '),'Fee neto satu kali: '+rup(row.fee),'Kontribusi produk indikatif: '+rup(row.total),'Total kombinasi indikatif: '+rup(scenario.total),'Metode: '+(row.kind==='Kredit'?'rata-rata × (bunga − FTP − biaya − risiko) / 100 × bulan / 12 + fee':'rata-rata × (FTP − bunga) / 100 × bulan / 12 + fee'),'Belum pricing resmi atau laba bersih. Kebutuhan dan asumsi wajib dikonfirmasi AO.'].join('\n')}
function xsCalcOpportunity(id,index){const p=c360Customer(id);if(!p||p.readOnly||(typeof pocReadOnly==='function'&&pocReadOnly()))return toast('Akses baca.');try{const result=xsCalcCompute(xsCalcDraft(id)),s=result.scenarios.find(x=>x.id===xsCalcScenario),r=result.rows[index];if(!s||!s.indices.includes(index)||!r||r.amount<=0||!xsCalcProducts(r.kind).some(x=>x.name===r.product))throw Error('Pilih produk aktif dan nominal tambahan yang valid.');const existing=db.opps.find(o=>o.profile===id&&mine(o)&&o.product===r.product&&o.outcome==='Aktif');if(existing)return go('Opportunity detail',existing.id);c360LaunchCrossSell(id,r.product,r.kind,xsCalcSnapshot(result,s,r));const f=document.querySelector('#form');if(f?.elements.value)f.elements.value.value=r.amount;if(f?.elements.basis)f.elements.basis.value=r.kind==='Kredit'?'Plafon indikatif':'Penempatan dana';if(f?.elements.need){f.elements.need.value='Sumber: Customer 360 / Cross-Sell Calculator\n'+xsCalcSnapshot(result,s,r);f.elements.need.dispatchEvent(new Event('input',{bubbles:true}))}}catch(e){toast(e.message)}}
const xsCalcIntelligenceBefore=c360Intelligence;
c360Intelligence=function(p){if(xsCalcCustomer===p.id)return xsCalcRender(p);return '<section class="xs-entry"><div><h2>Cross-Sell Calculator</h2><p>Bandingkan kombinasi Tabungan, Deposito dan Kredit dengan parameter dummy yang bisa diubah.</p></div>'+btn('Buka Cross-Sell Calculator',leadCall('xsCalcOpen',p.id),true)+'</section>'+xsCalcIntelligenceBefore(p)};
const xsCalcSummaryBefore=c360CrossSellSummary;
c360CrossSellSummary=function(p){return xsCalcSummaryBefore(p)+'<section class="xs-entry compact"><div><h3>Simulasikan kombinasi produk</h3><p>Hitung kontribusi indikatif sebelum menyiapkan penawaran.</p></div>'+btn('Cross-Sell Calculator',leadCall('xsCalcOpen',p.id))+'</section>'};
